    // Base case: Fibonacci of 0 is 0, and Fibonacci of 1 is 1
    if (n < 2) {
        return n;
    }

    // Recursively compute Fibonacci of (n-1)
    int fib_n_minus_1 = fibonacci(n - 1);

    // Recursively compute Fibonacci of (n-2)
    int fib_n_minus_2 = fibonacci(n - 2);

    // Sum the two previous Fibonacci values to get the current one
    int result = fib_n_minus_1 + fib_n_minus_2;

    return result;
